import{_ as t,p as d,q as r,Y as e}from"./framework-e1bed10d.js";const a={},h=e('<h1 id="_04内置函数" tabindex="-1"><a class="header-anchor" href="#_04内置函数" aria-hidden="true">#</a> 04内置函数</h1><p>函数是指一段可以被直接调用的程序或者代码</p><h2 id="聚合函数" tabindex="-1"><a class="header-anchor" href="#聚合函数" aria-hidden="true">#</a> 聚合函数</h2><p>分组查询中，经常会用到聚合函数，常见的聚合函数有以下几种：</p><table><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td>count(字段)</td><td>根据某个字段统计数量</td></tr><tr><td>max(字段)</td><td>某个字段为表中最大值的数据</td></tr><tr><td>min(字段)</td><td>某个字段为表中最小值的数据</td></tr><tr><td>avg(字段)</td><td>计算某个字段的平均值</td></tr><tr><td>sum(字段)</td><td>计算某个字段之和</td></tr></tbody></table><h2 id="字符串函数" tabindex="-1"><a class="header-anchor" href="#字符串函数" aria-hidden="true">#</a> 字符串函数</h2><table><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td>left(str,len)</td><td>左边的len个字符</td></tr><tr><td>right(str,len)</td><td>右边的len个字符</td></tr><tr><td>concat(S1,S2,...,Sn)</td><td>字符串拼接</td></tr><tr><td>lower(str)</td><td>转换为小写字符</td></tr><tr><td>upper(str)</td><td>转换为大写字符</td></tr><tr><td>ltrim(str)</td><td>去除左边的空格</td></tr><tr><td>rtrim(str)</td><td>去除右边的空格</td></tr><tr><td>trim(str)</td><td>去除字符串两边的空格</td></tr><tr><td>length(str)</td><td>长度</td></tr><tr><td>lpad(str,len,s)</td><td>用s左填充str到长度len</td></tr><tr><td>rpad(str,len,s)</td><td>用s右填充str到长度len</td></tr><tr><td>substring(str,from,len)</td><td>从from截取字符串str的len个字符</td></tr><tr><td>soundex()</td><td>转换为语音值</td></tr></tbody></table><h2 id="日期和时间处理" tabindex="-1"><a class="header-anchor" href="#日期和时间处理" aria-hidden="true">#</a> 日期和时间处理</h2><p>日期格式为<code>YYYY-MM-DD</code>，时间格式为<code>HH:MM:SS</code></p><p><strong>0 参数｜取当前时刻</strong></p><table><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td>curdate()</td><td>当前日期，如 2026-10-31（同义 current_date）</td></tr><tr><td>curtime()</td><td>当前时间，如 22:59:52（同义 current_time）</td></tr><tr><td>now()</td><td>当前日期和时间，如 2026-10-31 22:59:52（同义 current_timestamp）</td></tr><tr><td>sysdate()</td><td>实时时间，不受语句级快照影响</td></tr><tr><td>utc_timestamp()</td><td>UTC 时间</td></tr></tbody></table><p><strong>1 参数｜拆出日期/时间容器</strong></p><table><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td>date(expr)</td><td>取日期部分，date(&#39;2020-12-12 22:23:12&#39;) → 2020-12-12</td></tr><tr><td>time(expr)</td><td>取时间部分，time(&#39;2020-12-12 22:23:12&#39;) → 22:23:12</td></tr></tbody></table><p><strong>1 参数｜拆出数字（年→月→日→时→分→秒）</strong></p><table><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td>year(date)</td><td>年份部分</td></tr><tr><td>month(date)</td><td>月份部分</td></tr><tr><td>day(date)</td><td>天数部分（等价 dayofmonth）</td></tr><tr><td>hour(date)</td><td>小时部分</td></tr><tr><td>minute(date)</td><td>分钟部分</td></tr><tr><td>second(date)</td><td>秒部分</td></tr><tr><td>quarter(date)</td><td>季度（1~4）</td></tr><tr><td>week(date[, mode])</td><td>当年第几周</td></tr><tr><td>dayofyear(date)</td><td>一年中第几天</td></tr><tr><td>microsecond(date)</td><td>微秒部分</td></tr></tbody></table><p><strong>1 参数｜星期与周（口径不同，注意区分）</strong></p><table><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td>dayofweek(date)</td><td>1~7，<strong>1=周日</strong>、7=周六</td></tr><tr><td>weekday(date)</td><td>0~6，<strong>0=周一</strong>、6=周日</td></tr><tr><td>dayname(date)</td><td>星期英文名，如 saturday</td></tr><tr><td>week(date[, mode])</td><td>当年第几周，受 mode 影响</td></tr></tbody></table><p><strong>2 参数｜运算与格式化</strong></p><table><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td>date_add(date, interval count unit)</td><td>增加 count 个 unit，如 interval 1 month（unit 不加引号）</td></tr><tr><td>date_sub(date, interval count unit)</td><td>减少 count 个 unit</td></tr><tr><td>addtime(expr1, expr2)</td><td>增加一个时间，如 addtime(dt, &#39;01:30:00&#39;)</td></tr><tr><td>subtime(expr1, expr2)</td><td>减少一个时间</td></tr><tr><td>datediff(date1, date2)</td><td>相差天数，date1 - date2，只比较日期部分</td></tr><tr><td>timediff(t1, t2)</td><td>两个时间之差</td></tr><tr><td>timestampdiff(unit, d1, d2)</td><td>按指定粒度求差，unit 可为 second/minute/hour/day/month/year</td></tr><tr><td>date_format(date, format)</td><td>格式化为字符串，如 &#39;%Y-%m-%d&#39;</td></tr><tr><td>str_to_date(str, format)</td><td>字符串解析为日期，与上者互为反向</td></tr></tbody></table><h2 id="数值函数" tabindex="-1"><a class="header-anchor" href="#数值函数" aria-hidden="true">#</a> 数值函数</h2><table><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td>sin(x)</td><td>计算数值x的正弦值，x需为弧度制数值</td></tr><tr><td>cos(x)</td><td>计算数值x的余弦值，x需为弧度制数值</td></tr><tr><td>tan(x)</td><td>计算数值x的正切值，x需为弧度制数值</td></tr><tr><td>abs(x)</td><td>计算数值x的绝对值，支持整数、浮点数等数值类型</td></tr><tr><td>sqrt(x)</td><td>计算非负数x的算术平方根，x需大于等于0</td></tr><tr><td>mod(x, y)</td><td>计算x除以y的余数（模运算），可处理整数和小数的取余需求</td></tr><tr><td>floor(x)</td><td>对数值x进行向下取整，返回不大于x的最大整数</td></tr><tr><td>ceil(x)</td><td>对数值x进行向上取整，返回不小于x的最小整数</td></tr><tr><td>round(x[, y])</td><td>对数值x四舍五入，保留y位小数（y可选，默认0位，即取整）</td></tr><tr><td>exp(x)</td><td>计算自然常数e的x次幂，即自然指数函数</td></tr><tr><td>pi()</td><td>获取圆周率π的近似值，可用于几何相关计算</td></tr><tr><td>rand()</td><td>生成一个[0,1)区间内的随机浮点数，每次调用返回不同值</td></tr></tbody></table><h2 id="流程函数" tabindex="-1"><a class="header-anchor" href="#流程函数" aria-hidden="true">#</a> 流程函数</h2><table><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td>if(value, t, f)</td><td>如果value为true，则返回t，否则返回f</td></tr><tr><td>ifnull(value1,value2)</td><td>如果value1不为空则返回，否则返回value2</td></tr><tr><td>case when exp1 then res1 when exp2 then res2...else val [default val] end</td><td>如果val1为true，则返回res1,..，否则返回default默认值，when和then可以有多个，以end结尾</td></tr><tr><td>case exp when val1 then res1 when val2 then res2...else val [default val] end</td><td>如果exp等于val1，则返回res1,...，否则返回default默认值，when和then可以有多个，以end结尾</td></tr></tbody></table>',23),n=[h];function o(s,l){return d(),r("div",null,n)}const u=t(a,[["render",o],["__file","04function.html.vue"]]);export{u as default};
